      const quizQuestions = [
        {
          id: "language-types",
          prompt: "Which of these are programming languages?",
          help: "Select every option that is a language used to write software.",
          choices: ["Python", "HTML", "JavaScript", "JPEG"]
        },
        {
          id: "web-languages",
          prompt: "Which languages are commonly used for web development?",
          choices: ["JavaScript", "CSS", "SQL", "Swift"]
        },
        {
          id: "compiled-languages",
          prompt: "Which of these are typically compiled languages?",
          choices: ["C", "Rust", "Go", "Markdown"]
        }
      ];

      function ChoiceOption({ questionId, choice }) {
        const id = `${questionId}-${choice.toLowerCase().replace(/[^a-z0-9]+/g, "-")}`;

        return `
          <label class="choice" for="${id}">
            <input id="${id}" name="${questionId}" type="checkbox" value="${choice}">
            <span class="choice-text">${choice}</span>
          </label>
        `;
      }

      function QuestionField({ question }) {
        const helpId = `${question.id}-help`;
        const describedBy = question.help ? ` aria-describedby="${helpId}"` : "";
        const helpText = question.help ? `<p class="help-text" id="${helpId}">${question.help}</p>` : "";
        const choices = question.choices
          .map((choice) => ChoiceOption({ questionId: question.id, choice }))
          .join("");

        return `
          <div class="form-field">
            <fieldset${describedBy}>
              <legend>${question.prompt}</legend>
              ${helpText}
              <div class="choices">
                ${choices}
              </div>
            </fieldset>
          </div>
        `;
      }

      function QuizApp({ questions }) {
        const questionFields = questions
          .map((question) => QuestionField({ question }))
          .join("");

        return `
          <section class="quiz-shell" aria-labelledby="quiz-title">
            <p class="eyebrow">Multiple-answer quiz</p>
            <h1 id="quiz-title">Computer Languages Quiz</h1>
            <p class="intro">Choose all answers that apply for each question, then submit your selections.</p>
            <form id="computer-languages-quiz">
              ${questionFields}
              <div class="actions">
                <button type="submit">Submit answers</button>
                <p class="status" id="quiz-status" aria-live="polite"></p>
              </div>
            </form>
          </section>
        `;
      }

      document.querySelector("#quiz-root").innerHTML = QuizApp({ questions: quizQuestions });

      document.querySelector("#computer-languages-quiz").addEventListener("submit", (event) => {
        event.preventDefault();

        const answeredCount = quizQuestions.filter((question) => {
          return document.querySelectorAll(`input[name="${question.id}"]:checked`).length > 0;
        }).length;

        const status = document.querySelector("#quiz-status");
        status.textContent = `Submitted. You answered ${answeredCount} of ${quizQuestions.length} questions.`;
      });
    </script>
