    </main>

    <script>
      function ChoiceOption(input) {
        return {
          isSelected: () => input.checked
        };
      }

      function QuestionField(field) {
        const choices = Array.from(field.querySelectorAll('input[type="checkbox"]')).map(ChoiceOption);

        return {
          hasSelection: () => choices.some((choice) => choice.isSelected())
        };
      }

      function QuizApp(form) {
        const questions = Array.from(form.querySelectorAll(".form-field")).map(QuestionField);
        const status = document.querySelector("#quiz-status");

        form.addEventListener("submit", (event) => {
          event.preventDefault();

          const answeredCount = questions.filter((question) => question.hasSelection()).length;
          status.textContent = `Submitted. You answered ${answeredCount} of ${questions.length} questions.`;
        });
      }

      QuizApp(document.querySelector("#computer-languages-quiz"));
    </script>
  </body>
</html>
